"""Scientific report presentation. No inference or network access occurs here."""
import base64
import io
import json
from html import escape
from pathlib import PurePath

LIMITATIONS = [
    "Restoration improves the appearance of the input image but does not establish ground-truth surface properties.",
    "Hazard candidates are generated by OpenCV morphological operations and thresholding, not a deep-learning hazard classifier or confirmed physical hazards.",
    "Safe-region masks are algorithmic outputs, not certified landing-safety assessments.",
    "Landing-zone scores are heuristic rankings, not calibrated probabilities or guarantees of safe landing.",
    "Terrain displacement derived from image brightness is not actual elevation. Clearance and area are in image pixels, not calibrated physical units.",
    "Water-ice, thermal, spectral, radar and other resource layers are Unavailable unless valid data and models are supplied. Missing measurements must not be fabricated.",
    "The development hazard reference is derived photometric/synthetic imagery, not independently verified human ground truth.",
]
TITLE = "Lunar Image Restoration and Hazard-Candidate Analysis Report"


def display(value):
    if value is None or value == "":
        return "Unavailable"
    if isinstance(value, (dict, list)):
        return json.dumps(value, ensure_ascii=True)
    return format(value, ".6g") if isinstance(value, float) else str(value)


def sections(record, job):
    r = record["result"]
    telemetry = r.get("pipeline_telemetry") or {}
    restoration = r.get("restoration") or {}
    hazard = r.get("hazard_analysis") or {}
    model = dict(r.get("model_info") or {})
    mt = dict(telemetry.get("restoration") or {})
    if mt.get("checkpoint"):
        mt["checkpoint"] = PurePath(mt["checkpoint"]).name
    model.update(mt)
    historical = record.get("historical") or {}
    stages = record.get("stages") or {}
    candidates = r.get("landing_zones")
    selected = job.get("selected_lz_id")
    output = []
    def heading(s): output.append(("heading", s))
    def para(s): output.append(("para", s))
    def table(rows): output.append(("table", rows))
    def mapping(m, defaults=()):
        table([[k.replace("_", " "), display(m.get(k))] for k in dict.fromkeys([*defaults, *m])])

    heading("Report header")
    mapping({"project": "Lunar PSR Terminal", "report_id": job["report_id"],
             "analysis_id": r["mission_id"], "analysis_timestamp": r.get("timestamp"),
             "generation_timestamp": job.get("generated_at"),
             "input_filename": (r.get("input_info") or {}).get("filename"),
             "pipeline_version": r.get("software_version"), "model_checkpoint": mt.get("checkpoint")})
    heading("Executive summary and final status")
    mapping({"analysis_status": record["status"], "restoration": stages.get("restoration"),
             "hazard_candidate_analysis": stages.get("hazard"), "safe_region_analysis": stages.get("safe_region"),
             "candidate_count": len(candidates) if candidates is not None else None,
             "selected_candidate": selected, "pipeline_error": record.get("error")})
    para("COMPLETED: all required analysis stages completed. PARTIALLY COMPLETED: some results exist but a required stage or output is unavailable or failed. FAILED: no usable analysis output was produced. Report generation has its own status and never changes the analysis status.")
    heading("Input image information")
    mapping(record.get("source_info") or {}, ("filename", "width", "height", "channels", "format"))
    para("Source metadata describes the uploaded image. Processing decodes it to one grayscale channel. No geographic location or physical spatial resolution is inferred from the filename.")
    mapping(record.get("input_stats") or {}, ("brightness_mean", "brightness_std"))
    heading("Deep-learning restoration - current analysis")
    para("LunarUNet is a PyTorch U-Net-style image-restoration model with skip connections and bilinear upsampling. The output is a restored grayscale image.")
    mapping(model, ("name", "checkpoint", "epoch", "parameter_count", "val_loss"))
    mapping({k: v for k, v in restoration.items() if k != "image_b64"})
    para("Current ground-truth reference evaluation: Unavailable. The upload pipeline does not compute reference MAE, RMSE, R2, PSNR or SSIM for this image.")
    heading("Previously measured held-out restoration results")
    para("Separate evaluation of 300 held-out test image pairs (80/20 split, seed 42). These are historical model results, not measurements of the current image. Source: lunar_unet_complete_metrics.json.")
    mapping(historical.get("restoration") or {}, ("MAE (DN)", "RMSE (DN)", "R2", "PSNR (dB)", "SSIM"))
    heading("Hazard-candidate and safe-region analysis - current analysis")
    ht = telemetry.get("hazard") or {}
    mapping({k: ht.get(k) for k in ("engine", "mode", "method_description", "reference_type")})
    para("OpenCV uses Otsu-adaptive shadow thresholding, top-hat/black-hat morphology, morphological gradients, safety buffers and component filtering. Safe-region analysis takes the complement of the hazard-candidate mask. Canny edges are a display/scoring feature, not the V2 hazard decision.")
    mapping({k: hazard.get(k) for k in ("hazard_pixels", "safe_pixels", "total_pixels", "hazard_percentage", "safe_percentage", "edge_density", "min_safe_area")})
    para("Hazard and safe fractions are in [0, 1]. Legacy Canny/dilation defaults in the response are omitted because they do not describe the active V2 hazard configuration.")
    heading("Previously measured hazard-engine results")
    para("Separate 300-image held-out evaluation against a derived photometric/synthetic reference constructed from HR images with morphology and shadow thresholding; not independently verified human ground truth. Metrics are percentages, not current per-image predictions. Source: v2_final_comparison.json, selected operating mode.")
    mapping(historical.get("hazard", {}).get(ht.get("mode")) or {}, ("precision", "recall", "f1", "iou"))
    heading("Landing-zone candidates")
    para("The selected candidate is a recorded analysis selection or an explicit user selection captured when requesting this report. Scores are heuristic rankings, not probabilities or a guarantee of physical safety.")
    if candidates:
        keys = ["id", "score", "hazard_density", "clearance", "area", "rank"]
        table([["Candidate", "Score", "Hazard fraction", "Clearance (px)", "Area (px)", "Rank"]] +
              [[display(c.get(k)) for k in keys] for c in candidates])
        for c in candidates:
            para("Candidate " + display(c.get("id")))
            mapping({k: v for k, v in c.items() if k not in keys})
    else:
        para("No candidates returned." if candidates == [] else "Unavailable")
    heading("Visual results")
    for label, value in [
        ("Original input image (decoded upload)", record.get("original_b64")),
        ("Restored grayscale image", restoration.get("image_b64")),
        ("Hazard-candidate map", hazard.get("danger_map_b64")),
        ("Safe-region map", hazard.get("safe_region_b64")),
        ("Landing-zone overlay (pipeline-selected target)", hazard.get("landing_zones_overlay_b64")),
    ]:
        output.append(("image", (label, value))) if value else para(label + ": Unavailable")
    para("The persisted overlay shows the pipeline's original selected target; a later user selection is stated in the summary without changing the scientific maps.")
    heading("Resource layers and terrain measurements")
    resources = telemetry.get("resource_layers") or {}
    mapping({k: ("Available" if resources.get(k, {}).get("available") else "Unavailable")
             for k in dict.fromkeys(["water_ice_prospectivity", "thermal", "spectral", "radar", "illumination", *resources])})
    mapping(r.get("terrain_metrics") or {}, ("elevation_available", "slope_available", "roughness_available"))
    heading("Pipeline information")
    mapping({**{k: stages.get(k) for k in ["image_received", "validation", "restoration", "hazard", "safe_region", "landing_zones"]}, "report_generation": "COMPLETED"})
    mapping(r.get("processing_timeline") or {}, ("total_ms",))
    para("Durations are backend milliseconds. Hazard analysis, candidate generation and scoring share a combined interval; do not sum them. Zero-valued legacy intervals do not imply separately measured durations.")
    heading("Limitations and scientific disclaimer")
    for s in dict.fromkeys([*LIMITATIONS, *(r.get("scientific_limitations") or [])]): para(s)
    heading("Restored image statistics (no-reference diagnostics)")
    mapping(r.get("image_stats") or {}, ("brightness_mean", "brightness_std", "noise_level", "local_contrast"))
    return output


def render_html(record, job):
    parts = ["<!doctype html><html lang='en'><meta charset='utf-8'><meta name='viewport' content='width=device-width'><title>" + TITLE + "</title>",
             "<style>body{max-width:960px;margin:40px auto;padding:0 24px;font:15px/1.6 Arial;color:#172535;background:white}h1{font-size:26px}h2{margin-top:30px;border-bottom:1px solid #ccd5df}table{border-collapse:collapse;width:100%;margin:12px 0;table-layout:fixed}td{border:1px solid #dde3eb;padding:8px;overflow-wrap:anywhere;vertical-align:top}img{display:block;max-width:100%;max-height:550px;margin:12px auto}@media print{body{margin:0}h2{break-after:avoid}img{break-inside:avoid}}</style>",
             "<h1>" + TITLE + "</h1>"]
    for kind, value in sections(record, job):
        if kind in ("heading", "para"):
            tag = "h2" if kind == "heading" else "p"
            parts.append(f"<{tag}>{escape(value)}</{tag}>")
        elif kind == "table":
            parts.append("<table>" + "".join("<tr>" + "".join("<td>" + escape(display(v)) + "</td>" for v in row) + "</tr>" for row in value) + "</table>")
        elif kind == "image":
            # Validate persisted PNG payload; never accept external URLs or SVG markup.
            label, value = value
            data = base64.b64decode(value, validate=True)
            if not data.startswith(b'\x89PNG\r\n\x1a\n'): raise ValueError("Invalid report image")
            parts.append("<figure><figcaption>" + escape(label) + "</figcaption><img alt='" + escape(label, quote=True) + "' src='data:image/png;base64," + base64.b64encode(data).decode() + "'></figure>")
    return "".join(parts) + "</html>"


def render_pdf(record, job, path):
    from reportlab.lib import colors
    from reportlab.lib.styles import getSampleStyleSheet
    from reportlab.lib.pagesizes import A4
    from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, Image, KeepTogether
    from PIL import Image as PILImage
    styles = getSampleStyleSheet()
    styles["BodyText"].fontSize = 9
    styles["BodyText"].leading = 13
    story = [Paragraph(TITLE, styles["Title"]), Spacer(1, 12)]
    for kind, value in sections(record, job):
        if kind in ("heading", "para"):
            story.append(Paragraph(escape(value), styles["Heading2"] if kind == "heading" else styles["BodyText"]))
            story.append(Spacer(1, 6))
        elif kind == "table" and value:
            rows = [[Paragraph(escape(display(v)), styles["BodyText"]) for v in row] for row in value]
            widths = [165, 350] if len(value[0]) == 2 else [515 / len(value[0])] * len(value[0])
            table = Table(rows, colWidths=widths, repeatRows=1 if len(widths) > 2 else 0, hAlign="LEFT")
            table.setStyle(TableStyle([("GRID", (0,0), (-1,-1), .4, colors.HexColor("#d5dee8")), ("VALIGN", (0,0), (-1,-1), "TOP"), ("ROWBACKGROUNDS", (0,0), (-1,-1), [colors.white, colors.HexColor("#f3f6f9")]), ("TOPPADDING", (0,0), (-1,-1), 6), ("BOTTOMPADDING", (0,0), (-1,-1), 6)]))
            story.extend([table, Spacer(1, 8)])
        elif kind == "image":
            label, value = value
            data = base64.b64decode(value, validate=True)
            with PILImage.open(io.BytesIO(data)) as im: w, h = im.size
            scale = min(480 / w, 310 / h)
            story.append(KeepTogether([Paragraph(escape(label), styles["BodyText"]), Spacer(1,6), Image(io.BytesIO(data), width=w*scale, height=h*scale), Spacer(1,12)]))
    def footer(canvas, doc):
        canvas.saveState()
        canvas.setFont("Helvetica", 8)
        canvas.drawString(40, 22, "Lunar PSR Terminal | Report " + job["report_id"])
        canvas.drawRightString(A4[0]-40, 22, "Page " + str(doc.page))
        canvas.restoreState()
    SimpleDocTemplate(str(path), pagesize=A4, leftMargin=40, rightMargin=40, topMargin=36, bottomMargin=40,
                      title=TITLE, author="Lunar PSR Terminal").build(story, onFirstPage=footer, onLaterPages=footer)
